import re, sys, time
start = time.time()
held = 0
while True:
    value = float(re.search(r'some avg10=([0-9.]+)', open('/proc/pressure/cpu').read()).group(1))
    if value <= 1.0:
        held += 1
    else:
        held = 0
    if held >= 6:
        sys.exit(0)
    if time.time() - start >= 1800:
        sys.exit(1)
    time.sleep(5)

